import fs from 'node:fs';import {chromium} from '/validator/node_modules/playwright/index.mjs';
const html=fs.readFileSync('/input/game.html','utf8'),browser=await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_EXECUTABLE,args:['--no-sandbox','--disable-dev-shm-usage']});
const context=await browser.newContext({viewport:{width:390,height:844},isMobile:true,hasTouch:true});await context.tracing.start({screenshots:true,snapshots:true});const page=await context.newPage();await context.route('**/*',route=>route.request().url()==='http://game.invalid/'?route.fulfill({contentType:'text/html',body:html}):route.abort());await page.goto('http://game.invalid/');await page.locator('[data-testid=start]').tap();const session=await context.newCDPSession(page);
const result=[];for(const gesture of [{name:'inside-game',x:300,y:730,toY:210},{name:'toolbar-control',x:370,y:60,toY:5},{name:'counterfactual-pan-y',x:300,y:730,toY:210}]){if(gesture.name==='counterfactual-pan-y')await page.evaluate(()=>document.querySelector('#p2p-surface').style.touchAction='pan-y');await page.evaluate(()=>scrollTo(0,0));await page.waitForTimeout(200);const before=await page.evaluate(()=>({scroll:scrollY,height:document.documentElement.scrollHeight,viewport:innerHeight,root_touch_action:getComputedStyle(document.querySelector('#p2p-surface')).touchAction}));await session.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{x:gesture.x,y:gesture.y}]});for(let i=1;i<=10;i++){await session.send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[{x:gesture.x,y:gesture.y+(gesture.toY-gesture.y)*i/10}]});await page.waitForTimeout(20);}await session.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});await page.waitForTimeout(500);result.push({gesture:gesture.name,before,after:await page.evaluate(()=>({scroll:scrollY,height:document.documentElement.scrollHeight}))});fs.writeFileSync('/evidence/touch-scroll-'+gesture.name+'.png',await page.screenshot());}
fs.writeFileSync('/evidence/touch-scroll.png',await page.screenshot());await context.tracing.stop({path:'/evidence/touch-scroll.zip'});process.stdout.write(JSON.stringify({scope:'Supplemental actual Chromium touchscreen scroll gestures; original exact saved card game, no release reports changed',result}));await browser.close();
